            # 已排除 NaN / 无穷, 这里的比较不会抛 decimal.InvalidOperation;
            # Decimal('-0') > 0 为 False, 带符号零始终不可选。
            if w > 0:
                count += 1
        elif w > 0:
            count += 1
    return count


